import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    if sys.getrecursionlimit() < 20000:
        sys.setrecursionlimit(20000)

    def tokenize(expr: str) -> list[tuple[str, str]]:
        tokens: list[tuple[str, str]] = []
        i = 0
        n = len(expr)
        while i < n:
            ch = expr[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i
                while j < n and expr[j].isdigit():
                    j += 1
                tokens.append(("NUM", expr[i:j]))
                i = j
            elif ch.isalpha():
                j = i
                while j < n and expr[j].isalnum():
                    j += 1
                tokens.append(("ID", expr[i:j]))
                i = j
            elif i + 1 < n and expr[i : i + 2] in ("<=", ">=", "<>"):
                tokens.append(("OP", expr[i : i + 2]))
                i += 2
            elif ch in "+-*/(),:=<>":
                tokens.append(("OP", ch))
                i += 1
            else:
                raise ValueError(f"Unexpected character: {ch}")
        return tokens

    def parse_cell(name: str) -> tuple[int, int]:
        return ord(name[0]) - ord("A"), int(name[1:])

    def cell_name(col: int, row: int) -> str:
        return f"{chr(ord('A') + col)}{row}"

    memo: dict[str, int | str] = {}
    visiting: set[str] = set()

    def eval_cell(name: str) -> int | str:
        if name in memo:
            return memo[name]
        if name in visiting:
            return "#CYCLE!"
        if name not in cells:
            return 0

        raw = cells[name].strip()
        if not raw.startswith("="):
            val = int(raw)
            memo[name] = val
            return val

        visiting.add(name)
        tokens = tokenize(raw[1:])
        pos = 0

        def peek() -> tuple[str, str] | None:
            return tokens[pos] if pos < len(tokens) else None

        def consume() -> tuple[str, str]:
            nonlocal pos
            tok = tokens[pos]
            pos += 1
            return tok

        def parse_formula(active: bool) -> int | str:
            val = parse_term(active)
            while (tok := peek()) is not None and tok in (("OP", "+"), ("OP", "-")):
                op = consume()[1]
                if isinstance(val, str):
                    parse_term(False)
                else:
                    rhs = parse_term(active)
                    if isinstance(rhs, str):
                        val = rhs
                    elif active:
                        val = val + rhs if op == "+" else val - rhs
            return val

        def parse_term(active: bool) -> int | str:
            val = parse_unary(active)
            while (tok := peek()) is not None and tok in (("OP", "*"), ("OP", "/")):
                op = consume()[1]
                if isinstance(val, str):
                    parse_unary(False)
                else:
                    rhs = parse_unary(active)
                    if isinstance(rhs, str):
                        val = rhs
                    elif active:
                        if op == "*":
                            val = val * rhs
                        else:
                            if rhs == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(val) // abs(rhs)
                                val = -q if (val < 0) ^ (rhs < 0) else q
            return val

        def parse_unary(active: bool) -> int | str:
            if (tok := peek()) is not None and tok == ("OP", "-"):
                consume()
                val = parse_unary(active)
                if isinstance(val, str):
                    return val
                return -val if active else 0
            return parse_atom(active)

        def parse_atom(active: bool) -> int | str:
            tok = consume()
            if tok[0] == "NUM":
                return int(tok[1])
            if tok == ("OP", "("):
                val = parse_formula(active)
                consume()  # ')'
                return val
            ident = tok[1]
            if (nxt := peek()) is not None and nxt == ("OP", "("):
                consume()  # '('
                if ident == "IF":
                    left = parse_formula(active)
                    op = consume()[1]
                    right = parse_formula(active and not isinstance(left, str))
                    consume()  # ','
                    if isinstance(left, str) or isinstance(right, str):
                        err = left if isinstance(left, str) else right
                        parse_formula(False)
                        consume()  # ','
                        parse_formula(False)
                        consume()  # ')'
                        return err
                    if active:
                        if op == "=":
                            cond = left == right
                        elif op == "<>":
                            cond = left != right
                        elif op == "<":
                            cond = left < right
                        elif op == "<=":
                            cond = left <= right
                        elif op == ">":
                            cond = left > right
                        else:
                            cond = left >= right
                        then_val = parse_formula(cond)
                        consume()  # ','
                        else_val = parse_formula(not cond)
                        consume()  # ')'
                        return then_val if cond else else_val
                    else:
                        parse_formula(False)
                        consume()  # ','
                        parse_formula(False)
                        consume()  # ')'
                        return 0
                else:
                    # SUM, MIN, MAX
                    values: list[int] = []
                    err: str | None = None
                    while True:
                        if (
                            pos + 1 < len(tokens)
                            and tokens[pos][0] == "ID"
                            and tokens[pos + 1] == ("OP", ":")
                        ):
                            c1 = consume()[1]
                            consume()  # ':'
                            c2 = consume()[1]
                            if active and err is None:
                                col1, row1 = parse_cell(c1)
                                col2, row2 = parse_cell(c2)
                                r_lo, r_hi = min(row1, row2), max(row1, row2)
                                c_lo, c_hi = min(col1, col2), max(col1, col2)
                                for r in range(r_lo, r_hi + 1):
                                    for c in range(c_lo, c_hi + 1):
                                        cname = cell_name(c, r)
                                        if cname in cells:
                                            v = eval_cell(cname)
                                            if isinstance(v, str):
                                                err = v
                                                break
                                            values.append(v)
                                    if err is not None:
                                        break
                        else:
                            v = parse_formula(active and err is None)
                            if active and err is None:
                                if isinstance(v, str):
                                    err = v
                                else:
                                    values.append(v)
                        if peek() == ("OP", ","):
                            consume()
                        else:
                            break
                    consume()  # ')'
                    if not active:
                        return 0
                    if err is not None:
                        return err
                    if not values:
                        return 0
                    if ident == "SUM":
                        return sum(values)
                    if ident == "MIN":
                        return min(values)
                    return max(values)
            return eval_cell(ident) if active else 0

        result = parse_formula(True)
        visiting.remove(name)
        memo[name] = result
        return result

    return {name: eval_cell(name) for name in cells}
